package com.example.starter.pesticide;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    /**
     * 构造 409 冲突异常（幂等冲突、状态冲突、重复送检等）。
     */
    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    /**
     * 构造 404 不存在异常。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }
}

package com.example.starter.pesticide;

/**
 * 批次状态机：REPORTED 已报备 → SAMPLED 已抽样 → FROZEN 疑似冻结 / RELEASED 放行（终态）/ DISPOSED 处置结案（终态）。
 */
public enum BatchStatus {
    /** 已报备，待抽样 */
    REPORTED,
    /** 已抽样，可快检与判定放行 */
    SAMPLED,
    /** 疑似超标冻结，待定量复检 */
    FROZEN,
    /** 准入放行（终态） */
    RELEASED,
    /** 监督处置结案（终态） */
    DISPOSED;

    /**
     * 是否为终态（放行或处置结案）。
     */
    public boolean isTerminal() {
        return this == RELEASED || this == DISPOSED;
    }
}

