            ps.setString(1, requestId);
            ps.setString(2, fingerprint);
            ps.setLong(3, orderId);
            ps.setString(4, verdict);
            ps.setString(5, itemVersions);
            ps.setString(6, evidence);
            ps.setString(7, evidenceFingerprint);
