                row.qualified(), batch.status(), retentionUntil,
                row.createdAt().toInstant(ZoneOffset.UTC), replayed, late);
    }

    private LocalDateTime nowUtc() {
        return LocalDateTime.ofInstant(clock.instant(), ZoneOffset.UTC);
    }
}

